import {
  catchError,
  hashContent,
  logger
} from "./packager-tool-79gws1zn.js";
import {
  getFileSystem
} from "./packager-tool-0v3s8r01.js";

// ../case-tool/src/utils/resourcesStorage.ts
async function resolveResourcesStorageDir() {
  const fs = getFileSystem();
  return fs.path.join(fs.env.homedir(), ".uip", "case-resources");
}
async function saveResourceIndex(resources, resourceType) {
  const fs = getFileSystem();
  const dir = await resolveResourcesStorageDir();
  await fs.mkdir(dir);
  const indexPath = fs.path.join(dir, `${resourceType}-index.json`);
  const content = JSON.stringify(resources, null, 2);
  await fs.writeFile(indexPath, content);
  logger.debug(`Saved ${resources.length} ${resourceType} resources to index. Updating metadata...`);
  const hash = await hashContent(content);
  await saveIndexMetadata({
    lastSync: Date.now(),
    count: resources.length,
    hash
  }, resourceType);
  return resources.length;
}
async function loadResourceIndex(resourceType) {
  const fs = getFileSystem();
  const dir = await resolveResourcesStorageDir();
  const indexPath = fs.path.join(dir, `${resourceType}-index.json`);
  if (!await fs.exists(indexPath)) {
    throw new Error("No resource index found. Please run 'uip maestro case registry pull' to sync resources first.");
  }
  const [readError, content] = await catchError(fs.readFile(indexPath, "utf-8"));
  if (readError) {
    throw new Error(`Failed to load resource index: ${readError instanceof Error ? readError.message : String(readError)}`);
  }
  if (content === null || content.trim() === "") {
    throw new Error("No resource index found. Please run 'uip maestro case registry pull' to sync resources first.");
  }
  const [parseError, parsed] = await catchError(Promise.resolve().then(() => JSON.parse(content)));
  if (parseError) {
    throw new Error("No resource index found. Please run 'uip maestro case registry pull' to sync resources first.");
  }
  return parsed;
}
async function saveIndexMetadata(metadata, resourceType) {
  const fs = getFileSystem();
  const dir = await resolveResourcesStorageDir();
  await fs.mkdir(dir);
  const metaPath = fs.path.join(dir, `${resourceType}-index.meta.json`);
  await fs.writeFile(metaPath, JSON.stringify(metadata, null, 2));
}
async function loadIndexMetadata(resourceType) {
  const fs = getFileSystem();
  const dir = await resolveResourcesStorageDir();
  const metaPath = fs.path.join(dir, `${resourceType}-index.meta.json`);
  if (!await fs.exists(metaPath)) {
    return null;
  }
  const [error, metadata] = await catchError((async () => {
    const content = await fs.readFile(metaPath, "utf-8");
    if (content === null) {
      return null;
    }
    return JSON.parse(content);
  })());
  if (error) {
    return null;
  }
  return metadata;
}

export { saveResourceIndex, loadResourceIndex, saveIndexMetadata, loadIndexMetadata };

